templates.sql_template:
SELECT {date} AS date,
       SUM({active_flag}) AS dau
FROM {table}
WHERE {date} BETWEEN :start_date AND :end_date
GROUP BY {date}
ORDER BY {date}

SELECT {date} AS date,
       COUNT(DISTINCT {user_id}) AS dau
FROM {table}
WHERE {date} BETWEEN :start_date AND :end_date
GROUP BY {date}
ORDER BY {date}

SELECT {register_date} AS date,
       COUNT(*) AS new_users
FROM {table}
WHERE {register_date} BETWEEN :start_date AND :end_date
GROUP BY {register_date}
ORDER BY {register_date}

SELECT {date} AS date,
       SUM({revenue}) AS revenue
FROM {table}
WHERE {date} BETWEEN :start_date AND :end_date
GROUP BY {date}
ORDER BY {date}
